interface LangState {
  lang: Lang;
  hydrated: boolean;
  setLang: (l: Lang) => void;
  hydrate: () => void;
}

export const useLangStore = create<LangState>((set) => ({
  lang: 'en',
  hydrated: false,
  setLang: (l) => {
    set({ lang: l });
    try {
      window.localStorage.setItem(LS_KEY, l);
    } catch {
      // private mode
    }
  },
  hydrate: () => {
    try {
      const saved = window.localStorage.getItem(LS_KEY);
      if (saved && LANG_IDS.includes(saved as Lang)) set({ lang: saved as Lang, hydrated: true });
      else set({ hydrated: true });
    } catch {
      set({ hydrated: true });
    }
  },
}));

