    'rs.assume': 'अंदाजे: ~₹1 प्रति शीट कागद, शाई मोजलेल्या कव्हरेजप्रमाणे',
    'rs.bookletTitle': 'बुकलेट छपाई:',
    'rs.bookletBody': 'प्रिंट डायलॉगमध्ये आडवे + ड्युप्लेक्स निवडा, “flip on short edge” ठेवा. संपूर्ण फाइल छापा, शीट क्रमाने रचा, मधून एकदा घडा (विभाजक रेषा घड्याची खूण आहे) — झाले.',
