    'rs.iosBody': 'iOS पानाच्या आत PDF दाखवू शकत नाही — पण तुमची फाइल तयार आहे. फुल-स्क्रीन पाहण्यासाठी “उघडा” दाबा, किंवा छपाईसाठी “डाउनलोड” करा.',
    'rs.ocrNote': 'शोधण्यायोग्य मजकूर थर जोडला — PDF व्ह्यूअरमध्ये Ctrl+F / शोध वापरून पहा.',
    'st.files': 'फाइल्स ऑप्टिमाइझ',
