    'st.paper': 'कमी कागद वापरला',
    'st.money': 'पैसे वाचले',
    'st.note': 'निनावी, एकत्रित आकडेवारी — ना अकाउंट, ना ट्रॅकिंग, ना अपलोड. ₹ अंदाज: ~₹1/शीट कागद + शाई.',
    'sf.title': '“{f}” ला Printifier सर्व्हर लागतो',
    'sf.body': 'हे वैशिष्ट्य Printifier च्या छोट्या सर्व्हर-मेंदूवर चालते, जी हे स्टॅटिक होस्टिंग देऊ शकत नाही. मुख्य टूल्स — मांडणी, शाई-बचत, बुकलेट, प्रीसेट, डाउनलोड व शेअर — सर्व तुमच्या ब्राउझरमध्ये 100% चालतात व येथेच काम करतात.',
    'sf.whyBtn': 'का?',
    'sf.whyHosting': 'ही साइट GitHub Pages वर होस्ट आहे: मोफत, जलद, स्टॅटिक फाइल होस्टिंग — बॅकएंड नाही. AI सल्ला, आवाज व क्लाउड सिंक यांना चालू सर्व्हर प्रक्रिया लागते, म्हणून या मिररवर ते स्रोतातच बंद ठेवले आहेत — लपवलेले नाहीत, फक्त प्रामाणिकपणे.',
    'sf.whyWorks': 'बाकी सर्व शुद्ध ब्राउझर-जादू आहे: पान निवड, शाई-बचत सुधारणा, OCR, N-up मांडणी, बुकलेट, प्रीसेट, डाउनलोड, WhatsApp/Telegram शेअर — सर्व येथेच चालते, ऑफलाइनही.',
    'sf.howToGet': 'संपूर्ण अनुभव हवा आहे? Printifier तुमच्या स्वतःच्या संगणकावर चालवा (bun install → bun run dev), मुख्य टूल्ससाठी Android ॲप ऑफलाइन वापरा, किंवा होस्टेड-सर्व्हर रिलीझची वाट पहा — कोड तयार आहे, README पहा.',
    'sf.ok': 'समजले',
    'sf.feature.stats': 'कम्युनिटी आकडेवारी',
    'sf.feature.preset': 'शेअर केलेली प्रीसेट लिंक',
    'faq.title': 'प्रश्न',
    'faq.sub': 'प्रिंट दाबण्यापूर्वी विचारायला येऊ शकणारे सर्व काही.',
    'faq1.q': 'माझ्या फाइल्स सर्व्हरवर जातात का?',
    'faq1.a': 'नाही. सर्व काही — पार्सिंग, फिल्टर व PDF निर्मिती — तुमच्या ब्राउझरमध्येच चालते. नोट्स डिव्हाइसमधून बाहेर जात नाहीत, आणि पान लोड झाल्यावर ऑफलाइन असले तरी चालते.',
    'faq2.q': 'प्रत्यक्षात किती कागद व शाई वाचू शकतो?',
    'faq2.a': 'गडद पार्श्वभूमीच्या व्याख्यान स्लाईडमध्ये रंग उलटा + इंक सेव्हरने 60–85% शाई वाचते, आणि प्रति शीट 3–4 स्लाईड लावल्यास कागद 60–75% कमी लागतो. अचूक आकडे प्रोसेसिंगनंतर दिसतात.',
    'faq3.q': 'कोणत्या PDF सर्वात चांगल्या चालतात?',
    'faq3.a': 'गडद रंगाचे व्याख्यान डेक (Physics Wallah स्टाइल), स्कॅन केलेली नोट्स आणि मजकूरप्रधान प्रेझेंटेशन. स्वच्छ पांढऱ्या हँडआउटसाठी रंग उलटा ऐवजी ग्रेस्केल किंवा B&W + 30–50% इंक सेव्हर वापरून पहा.',
    'faq4.q': 'कोणत्याही डिव्हाइसवर चालते?',
    'faq4.a': 'हो — फोन, टॅबलेट, लॅपटॉप किंवा डेस्कटॉप. संपूर्ण टूल कोणत्याही आधुनिक ब्राउझरमध्ये (Chrome, Safari, Edge, Firefox) चालते, काहीही इंस्टॉल करावे लागत नाही. जुन्या फोनवर मोठ्या फाइल्सला थोडा जास्त वेळ लागतो, त्यामुळे प्रोसेस होताना टॅब उघडा ठेवा.',
    'faq5.q': 'iPhone वर पूर्वावलोकन रिकामे का दिसते?',
    'faq5.a': 'iOS Safari पानाच्या आत PDF दाखवू शकत नाही. “उघडा” दाबून PDF संपूर्ण टॅबमध्ये पहा किंवा थेट “डाउनलोड” दाबा — फाइल संपूर्ण आहे आणि उत्तम छापली जाईल.',
    'faq6.q': 'निकालाचा PDF शोधण्यायोग्य किंवा पुन्हा संपादनयोग्य आहे का?',
    'faq6.a': 'डीफॉल्टने तो उच्च-गुणवत्तेचा इमेज-आधारित PDF आहे (त्यामुळेच शाई बचत शक्य होते) — पण सुधारा येथे “शोधण्यायोग्य PDF (OCR)” चालू करा, अदृश्य मजकूर थर जोडला जातो आणि शोध, निवड, कॉपी सर्व चालते. पान क्रमांक व विभाजक रेषा नेहमी खरे व्हेक्टर घटक असतात.',
    'faq7.q': 'Android ॲप आहे का?',
    'faq7.a': 'हो! तळटीपातून APK डाउनलोड करा — Stable बिल्ड स्थिर व नवशिक्यांसाठी सुरक्षित आहे, तर Beta बिल्डला नवे वैशिष्ट्य आधी मिळतात. दोन्ही पूर्णपणे ऑफलाइन चालतात आणि डाउनलोड केलेला PDF थेट तुमच्या फोनवर साठतो.',
    'faq8.q': 'Google Drive किंवा Dropbox मधून PDF आणता येते का?',
    'faq8.a': 'हो — अपलोड स्क्रीनवर “क्लाउडमधून इंपोर्ट” दाबून शेअर लिंक पेस्ट करा (फाइल “Anyone with the link” ठेवा). सर्व्हर ती एकदा आणून थेट तुमच्या ब्राउझरकडे पाठवतो; काहीही साठवले जात नाही.',
