    'tour.s1.t': 'Printifier-க்கு வரவேற்கிறோம்',
    'tour.s1.b': 'கனமான விரிவுரை PDF-ஐ அச்சு-நட்பு தாள்களாக மாற்றுங்கள் — ஒரு பக்கத்தில் அதிக ஸ்லைடுகள், குறைவான மை, தெளிவான அச்சு. எல்லாம் உங்கள் உலாவியிலேயே இயங்குகிறது; உங்கள் கோப்புகள் சாதனத்தை விட்டு வெளியேறாது.',
    'tour.s1.c1': 'N-up அமைப்பு',
    'tour.s1.c2': 'மை சேமிப்பு',
    'tour.s1.c3': 'புக்லெட் முறை',
    'tour.s1.c4': '100% தனிப்பட்டது',
    'tour.s2.t': 'உங்களுக்காக மாற்றுங்கள்',
    'tour.s2.b': 'ஒரு தோற்றத்தைத் தேர்வு செய்யுங்கள் — முழு ஆப்பும் உடனே மாறும். 12 தீம்களும் 10 பின்னணி வடிவங்களும் மேலே உள்ள பாலெட் பொத்தானில், அல்லது எப்போது வேண்டுமானாலும் ⌘K / Ctrl+K அழுத்துங்கள்.',
    'tour.s2.hint': 'நேரலையில் பார்க்க ஹோவர் செய்யுங்கள் — வைத்திருக்க தட்டவும்',
    'tour.s2.dark': 'இருள்',
    'tour.s2.light': 'ஒளி',
    'tour.s2.live': 'நேரலை முன்தோற்றம்',
    'tour.s2.patterns': 'பின்னணி வடிவம்',
    'tour.s3.t': 'ஒரு உண்மையான எடுத்துக்காட்டு',
    'tour.s3.b': 'இது உண்மையான 41-பக்க இருண்ட விரிவுரை PDF — பழமையான செய்முறையில் செயலாக்கப்பட்டது (தலைகீழ், மை-சேமிப்பு, தாளுக்கு 3 ஸ்லைடுகள்). எதுவும் நாடகம் இல்லை.',
    'tour.s3.before': 'முன் · {n} தாள்கள்',
    'tour.s3.after': 'பின் · {n} பக்கங்கள்',
