    'tour.s3.load': 'இந்த PDF-ஐ ஏற்றி முயற்சிக்கவும்',
    'tour.s3.full': 'முழு முன்/பின் பாருங்கள்',
    'tour.s4.t': 'இப்போது உங்கள் முறை',
    'tour.s4.b': 'எந்த விரிவுரை PDF-ஐயும் போடுங்கள், ஸ்லைடர்களை சரிசெய்து அச்சு-தயார் கோப்பை பதிவிறக்குங்கள். மூன்று படிகள்: பதிவேற்றம் → மேம்படுத்தல் → அச்சு.',
    'tour.s4.s1': 'உங்கள் PDF-ஐ பதிவேற்றுங்கள்',
    'tour.s4.s2': 'மேம்படுத்தி அமைக்கவும்',
