    'en.stains.inv': 'பரிந்துரை — இருண்ட பழுப்பு & கடற்படை-நீல ஸ்லைடு பின்னணிகள் தலைகீழாக்கப்படும்போது ஏற்படும் நீல/சயன் நிழலை நீக்குகிறது; தலைகீழாக்கப்பட்ட சிவப்பு நிரப்புப் பகுதிகளும் சுத்தமாகும். கையெழுத்தும் படங்களும் பாதுகாக்கப்படும்.',
    'en.stains.light': 'ஸ்லைடுகளுக்கு இடையில் உள்ள வெளிர்-நீல நீர்வண்ணக் கறைகளையும், கேள்வி எண்கள் & விடைக் குறிப்புகளுக்குப் பின்னால் உள்ள சயன் நிரப்புகளையும் நீக்குகிறது — கையெழுத்து, படங்கள், உரை பாதுகாக்கப்படும். வெள்ளை பின்னணி நோட்ஸுக்குப் பரிந்துரை.',
    'en.logo': 'லோகோ / வாட்டர்மார்க்கை அகற்று',
    'en.logo.d': 'பக்கத்தில் நேரடியாக லோகோவைச் சுற்றிப் பெட்டி வரையுங்கள் — எந்த மூலையிலும் (மேல்-வலப்புற வாட்டர்மார்க் போல) — அது ஒவ்வொரு பக்கத்திலும் அழிக்கப்படும். அல்லது கீழே உள்ள ஸ்லைடரால் மேல் பட்டையை அகற்றுங்கள்.',
    'en.logo.off': 'முடக்கு',
    'en.logo.aria': 'தலைப்புப் பட்டை அகற்றும் உயரம்',
    'en.logo.pick': 'பக்கத்தில் பகுதியைத் தேர்ந்தெடு',
