    'sf.whyWorks': 'বাকি সবকিছু নিছক ব্রাউজার-জাদু: পৃষ্ঠা নির্বাচক, কালি-সাশ্রয়ী উন্নতি, OCR, N-up লেআউট, বুকলেট, প্রিসেট, ডাউনলোড, WhatsApp/Telegram শেয়ার — সব এখানেই চলে, অফলাইনেও।',
    'sf.howToGet': 'পুরো অভিজ্ঞতা চান? নিজের কম্পিউটারে Printifier চালান (bun install → bun run dev), মূল টুলগুলির জন্য Android অ্যাপ ব্যবহার করুন, বা হোস্টেড-সার্ভার রিলিজের অপেক্ষা করুন — কোড প্রস্তুত, README দেখুন।',
    'sf.ok': 'বুঝেছি',
    'sf.feature.stats': 'কমিউনিটি স্ট্যাটস',
    'sf.feature.preset': 'শেয়ার করা প্রিসেট লিংক',
    'faq.title': 'প্রশ্নোত্তর',
    'faq.sub': 'প্রিন্ট চাপার আগে যা কিছু জানতে ইচ্ছে করতে পারে।',
    'faq1.q': 'আমার ফাইল কি সার্ভারে আপলোড হয়?',
    'faq1.a': 'না। সবকিছু — পার্সিং, ফিল্টার আর PDF তৈরি — আপনার ব্রাউজারেই চলে। নোট কখনও ডিভাইসের বাইরে যায় না, আর পেজ লোড হওয়ার পর অফলাইনেও এটি চলে।',
    'faq2.q': 'আসলে কত কাগজ ও কালি বাঁচানো যায়?',
    'faq2.a': 'গাঢ় পটভূমির লেকচার স্লাইডে Invert + কালি সাশ্রয় দিয়ে 60–85% কালি বাঁচে, আর এক শিটে 3–4টি স্লাইড সাজালে কাগজ 60–75% কম লাগে। আপনার সঠিক সংখ্যাগুলি প্রসেসিংয়ের পরে দেখানো হয়।',
    'faq3.q': 'কোন PDF সবচেয়ে ভালো চলে?',
    'faq3.a': 'গাঢ় রঙের লেকচার ডেক (Physics Wallah স্টাইল), স্ক্যান করা নোট আর লেখা-প্রধান প্রেজেন্টেশন। পরিষ্কার সাদা হ্যান্ডআউটের জন্য Invert-এর বদলে Grayscale বা B&W + 30–50% কালি সাশ্রয় আজমান।',
    'faq4.q': 'এটি কি সব ডিভাইসে চলে?',
    'faq4.a': 'হ্যাঁ — ফোন, ট্যাবলেট, ল্যাপটপ বা ডেস্কটপ। পুরো টুল যেকোনো আধুনিক ব্রাউজারে (Chrome, Safari, Edge, Firefox) চলে, ইনস্টল করার কিছু নেই। পুরনো ফোনে বড় ফাইলে একটু বেশি সময় লাগে, তাই প্রসেসিংয়ের সময় ট্যাব খোলা রাখুন।',
    'faq5.q': 'আমার iPhone-এ প্রিভিউ ফাঁকা কেন দেখায়?',
    'faq5.a': 'iOS Safari পৃষ্ঠার ভেতরে PDF দেখাতে পারে না। “Open” চেপে পুরো ট্যাবে দেখুন, বা সরাসরি “Download” চাপুন — ফাইলটি পুরোপুরি ঠিক আছে এবং দুর্দান্ত ছাপা হবে।',
    'faq6.q': 'আউটপুট PDF কি অনুসন্ধানযোগ্য বা আবার সম্পাদনাযোগ্য?',
    'faq6.a': 'ডিফল্টে এটি উচ্চ-গুণমানের ইমেজ-ভিত্তিক PDF (কালির সাশ্রয় এর জন্যই সম্ভব) — কিন্তু উন্নত করুন ধাপে “অনুসন্ধানযোগ্য PDF (OCR)” চালু করলে অদৃশ্য একটি লেখা স্তর যোগ হয়, যাতে অনুসন্ধান, নির্বাচন ও কপি সবই চলে। পৃষ্ঠা নম্বর ও বিভাজক সবসময় সত্যিকারের ভেক্টর।',
    'faq7.q': 'Android অ্যাপ আছে?',
    'faq7.a': 'হ্যাঁ! ফুটার থেকে APK ডাউনলোড করুন — Stable বিল্ড স্থির ও নতুনদের জন্য নিরাপদ, আর Beta বিল্ডে নতুন ফিচার আগে আসে। দুটিই পুরোপুরি অফলাইনে চলে আর ডাউনলোড করা PDF সরাসরি ফোনে সেভ হয়।',
    'faq8.q': 'Google Drive বা Dropbox থেকে PDF আনা যায়?',
    'faq8.a': 'হ্যাঁ — আপলোড স্ক্রিনে “ক্লাউড থেকে ইমপোর্ট” চেপে শেয়ার লিংক পেস্ট করুন (ফাইলটি “Anyone with the link” রাখুন)। সার্ভার একবার এনে সরাসরি আপনার ব্রাউজারে পাঠায়; কিছুই সংরক্ষণ করা হয় না।',
