    'rs.duplexBody': 'બેજોડ/જોડ ફાઇલોમાં વહેંચો: પહેલાં બેજોડવાળી છાપો, ઢગલો પલટાવો, પછી જોડવાળી પાછળની બાજુ છાપો.',
