    'rs.odd': 'બેજોડ શીટ ({n})',
    'rs.even': 'જોડ શીટ ({n})',
    'rs.iosBody': 'iOS પાનાંની અંદર PDF બતાવી શકતું નથી — પણ તમારી ફાઇલ તૈયાર છે. પૂરી સ્ક્રીને જોવા Open દબાવો, અથવા છાપવા માટે Download કરી સાચવો.',
    'rs.ocrNote': 'શોધી શકાય તેવી ટેક્સ્ટ લેયર ઉમેરાઈ — PDF વ્યૂઅરમાં Ctrl+F / શોધ અજમાવો.',
    'st.files': 'ઑપ્ટિમાઇઝ થયેલી ફાઇલો',
    'st.pagesCompacted': 'કોમ્પેક્ટ થયેલાં પાનાં',
    'st.paper': 'ઓછો કાગળ વપરાયો',
    'st.money': 'પૈસા બચ્યાં',
    'st.note': 'ગુમનામ, સંકલિત આંકડા — ન એકાઉન્ટ, ન ટ્રેકિંગ, ન અપલોડ. ₹ અંદાજ: ~₹1/શીટ કાગળ + સ્યાહી.',
    'sf.title': '“{f}” ને Printifier સર્વર જોઈએ છે',
    'sf.body': 'આ ફીચર Printifier ના નાના સર્વર-બ્રેઇન પર ચાલે છે, જે આ સ્ટેટિક હોસ્ટિંગ આપી શકતું નથી. બાકીનાં મુખ્ય ટૂલ્સ — લેઆઉટ, સ્યાહી-બચત, બુકલેટ, પ્રીસેટ, ડાઉનલોડ અને શેર — બધું તમારા બ્રાઉઝરમાં 100% ચાલે છે અને અહીં જ કામ કરે છે.',
    'sf.whyBtn': 'કેમ?',
    'sf.whyHosting': 'આ સાઇટ GitHub Pages પર હોસ્ટ છે: મફત, ઝડપી, સ્ટેટિક ફાઇલ-હોસ્ટિંગ — કોઈ બેકએન્ડ નહીં. AI સલાહ, અવાજ અને ક્લાઉડ સિંકને ચાલુ સર્વર પ્રક્રિયા જોઈએ, એટલે આ મિરર પર તે સ્ત્રોત પર જ બંધ રહે છે — છુપાવેલાં નથી, ઇમાનદારી છે.',
    'sf.whyWorks': 'બાકી બધું શુદ્ધ બ્રાઉઝર-જાદુ છે: પાનાં પસંદગી, સ્યાહી-બચત સુધાર, OCR, N-અપ લેઆઉટ, બુકલેટ, પ્રીસેટ, ડાઉનલોડ, WhatsApp/Telegram શેર — બધું અહીં ચાલે છે, ઑફલાઇન પણ.',
    'sf.howToGet': 'પૂરો અનુભવ જોઈએ છે? Printifier પોતાના કમ્પ્યુટર પર ચલાવો (bun install → bun run dev), મુખ્ય ટૂલ્સ ઑફલાઇન વાપરવા Android ઍપ લો, અથવા હોસ્ટેડ-સર્વર રિલીઝની રાહ જુઓ — કોડ તૈયાર છે, README જુઓ.',
    'sf.ok': 'સમજાઈ ગયું',
    'sf.feature.stats': 'કમ્યુનિટી આંકડા',
    'sf.feature.preset': 'શેર થયેલી પ્રીસેટ લિંક',
    'faq.title': 'પ્રશ્નો-જવાબ',
    'faq.sub': 'પ્રિન્ટ દબાવતાં પહેલાં મનમાં આવી શકે તે બધું જ.',
    'faq1.q': 'શું મારી ફાઇલો સર્વર પર અપલોડ થાય છે?',
    'faq1.a': 'ના. બધું — પાર્સિંગ, ફિલ્ટર અને PDF બનાવવું — તમારા બ્રાઉઝરમાં જ ચાલે છે. નોંધ ક્યારેય ડિવાઇસમાંથી બહાર જતી નથી, અને પેજ લોડ થયા પછી ઑફલાઇન હોય તો પણ ચાલે છે.',
    'faq2.q': 'કેટલો કાગળ અને સ્યાહી ખરેખર બચે?',
    'faq2.a': 'ઘાટા બેકગ્રાઉન્ડવાળા લેક્ચર સ્લાઇડમાં Invert + સ્યાહી બચતથી 60–85% સ્યાહી બચે છે, અને એક શીટ પર 3–4 સ્લાઇડ ગોઠવવાથી કાગળ 60–75% ઓછો લાગે છે. ચોક્કસ આંકડા પ્રોસેસિંગ પછી દેખાય છે.',
    'faq3.q': 'કઈ PDF સૌથી સારી ચાલે?',
    'faq3.a': 'ઘાટા રંગવાળાં લેક્ચર ડેક (Physics Wallah સ્ટાઇલ), સ્કેન કરેલી નોંધ અને લખાણ-પ્રધાન પ્રેઝન્ટેશન. સાફ સફેદ હેન્ડઆઉટ માટે Invert ના બદલે Grayscale/કાળું-સફેદ + 30–50% સ્યાહી બચત અજમાવો.',
    'faq4.q': 'કોઈપણ ડિવાઇસ પર ચાલે છે?',
    'faq4.a': 'હા — ફોન, ટેબ્લેટ, લેપટૉપ કે ડેસ્કટૉપ. આખું ટૂલ કોઈપણ આધુનિક બ્રાઉઝર (Chrome, Safari, Edge, Firefox) માં ચાલે છે, ઇન્સ્ટૉલ કરવાનું કંઈ નથી. જૂના ફોન પર મોટી ફાઇલને થોડો વધુ સમય લાગે, ટૅબ ખુલ્લું રાખો.',
    'faq5.q': 'મારા iPhone પર પ્રીવ્યૂ ખાલી કેમ દેખાય છે?',
    'faq5.a': 'iOS Safari પાનાંની અંદર PDF બતાવી શકતું નથી. “Open” દબાવી પૂરા ટૅબમાં ખોલો અથવા સીધા “Download” કરો — ફાઇલ પૂરી છે અને એકદમ સરસ છપાશે.',
    'faq6.q': 'શું આઉટપુટ PDF શોધી/ફેરફાર કરી શકાય છે?',
    'faq6.a': 'મૂળભૂત રીતે તે ઊંચી ગુણવત્તાવાળી ઇમેજ-આધારિત PDF છે (સ્યાહી-બચત આનાથી જ શક્ય બને છે) — પણ સુધારોમાં “શોધી શકાય તેવી PDF (OCR)” ચાલુ કરો તો અદ્રશ્ય ટેક્સ્ટ લેયર ઉમેરાય છે, જેથી શોધ, પસંદગી અને કૉપિ બધું ચાલે. પાનાં નંબર અને વિભાજન લીટીઓ હંમેશાં અસલી વેક્ટર હોય છે.',
    'faq7.q': 'શું Android ઍપ છે?',
    'faq7.a': 'હા! ફૂટરમાંથી APK ડાઉનલોડ કરો — Stable બિલ્ડ સ્થિર અને નવી શરૂઆત માટે સલામત છે, જ્યારે Beta બિલ્ડમાં નવાં ફીચર પહેલાં આવે છે. બંને સંપૂર્ણ ઑફલાઇન ચાલે છે અને ડાઉનલોડ કરેલી PDF સીધા ફોનમાં સેવ થાય છે.',
    'faq8.q': 'શું Google Drive કે Dropbox માંથી PDF લાવી શકાય?',
    'faq8.a': 'હા — અપલોડ સ્ક્રીન પર “ક્લાઉડમાંથી આયાત” દબાવી શેર લિંક પેસ્ટ કરો (ફાઇલ “Anyone with the link” રાખો). સર્વર તેને એક વાર લાવી સીધા તમારા બ્રાઉઝરમાં મોકલે છે; કંઈ સંગ્રહાતું નથી.',
    'labs.title': 'લેબ્સ',
