    'st.note': 'ਗੁਮਨਾਮ, ਇਕੱਠੇ ਕੀਤੇ ਅੰਕੜੇ — ਨਾ ਅਕਾਊਂਟ, ਨਾ ਟਰੈਕਿੰਗ, ਨਾ ਅੱਪਲੋਡ। ₹ ਅੰਦਾਜ਼ਾ: ~₹1/ਸ਼ੀਟ ਕਾਗ਼ਜ਼ + ਸਿਆਹੀ।',
    'sf.title': '“{f}” ਨੂੰ Printifier ਸਰਵਰ ਚਾਹੀਦਾ ਹੈ',
    'sf.body': 'ਇਹ ਫ਼ੀਚਰ Printifier ਦੇ ਛੋਟੇ ਸਰਵਰ-ਦਿਮਾਗ਼ ਤੇ ਚੱਲਦਾ ਹੈ, ਜੋ ਸਟੈਟਿਕ ਹੋਸਟਿੰਗ ਤੇ ਉਪਲਬਧ ਨਹੀਂ। ਬਾਕੀ ਸਭ — ਲੇਆਉਟ, ਸਿਆਹੀ-ਬਚਤ, ਬੁੱਕਲੈਟ, ਪ੍ਰੀਸੈਟ, ਡਾਊਨਲੋਡ ਤੇ ਸਾਂਝਾ — ਤੁਹਾਡੇ ਬਰਾਊਜ਼ਰ ਵਿੱਚ 100% ਚੱਲਦਾ ਹੈ।',
    'sf.whyBtn': 'ਕਿਉਂ?',
    'sf.whyHosting': 'ਇਹ ਸਾਈਟ GitHub Pages ਤੇ ਹੈ: ਮੁਫ਼ਤ, ਤੇਜ਼, ਸਟੈਟਿਕ ਹੋਸਟਿੰਗ — ਬਿਨਾਂ ਬੈਕਐਂਡ। AI ਸਲਾਹ, ਆਵਾਜ਼ ਤੇ ਕਲਾਉਡ ਸਿੰਕ ਲਈ ਜੀਉਂਦਾ ਸਰਵਰ ਚਾਹੀਦਾ ਹੈ, ਇਸ ਲਈ ਇਸ ਮਿਰਰ ਤੇ ਇਹ ਬੰਦ ਰਹਿੰਦੇ ਹਨ — ਲੁਕੇ ਨਹੀਂ, ਇਮਾਨਦਾਰੀ ਨਾਲ।',
    'sf.whyWorks': 'ਬਾਕੀ ਸਭ ਸ਼ੁੱਧ ਬਰਾਊਜ਼ਰ-ਜਾਦੂ ਹੈ: ਪੰਨਾ ਚੋਣ, ਸਿਆਹੀ-ਬਚਤ, OCR, N-up ਲੇਆਉਟ, ਬੁੱਕਲੈਟ, ਪ੍ਰੀਸੈਟ, ਡਾਊਨਲੋਡ, WhatsApp/Telegram ਸਾਂਝਾ — ਸਭ ਇੱਥੇ ਚੱਲਦਾ ਹੈ, ਆਫ਼ਲਾਈਨ ਵੀ।',
    'sf.howToGet': 'ਪੂਰਾ ਤਜਰਬਾ ਚਾਹੀਦਾ ਹੈ? Printifier ਆਪਣੇ ਕੰਪਿਊਟਰ ਤੇ ਚਲਾਓ (bun install → bun run dev), Android ਐਪ ਨਾਲ ਕੋਰ-ਟੂਲ ਆਫ਼ਲਾਈਨ ਵਰਤੋ, ਜਾਂ ਹੋਸਟਡ-ਸਰਵਰ ਰੀਲਿਜ਼ ਦੀ ਉਡੀਕ ਕਰੋ — ਕੋਡ ਤਿਆਰ ਹੈ, README ਵੇਖੋ।',
