    'faq.title': 'ਸਵਾਲ-ਜਵਾਬ',
    'faq.sub': 'ਪ੍ਰਿੰਟ ਦਬਾਉਣ ਤੋਂ ਪਹਿਲਾਂ ਜੋ ਕੁਝ ਵੀ ਜਿਜਞਾਸਾ ਹੋ ਸਕਦੀ ਹੈ।',
    'faq1.q': 'ਕੀ ਮੇਰੀਆਂ ਫ਼ਾਈਲਾਂ ਸਰਵਰ ਤੇ ਜਾਂਦੀਆਂ ਹਨ?',
    'faq1.a': 'ਨਹੀਂ। ਸਭ ਕੁਝ — ਪਾਰਸਿੰਗ, ਫ਼ਿਲਟਰ ਤੇ PDF ਬਣਾਉਣਾ — ਤੁਹਾਡੇ ਬਰਾਊਜ਼ਰ ਵਿੱਚ ਹੀ ਚੱਲਦਾ ਹੈ। ਨੋਟਸ ਡਿਵਾਈਸ ਤੋਂ ਬਾਹਰ ਨਹੀਂ ਜਾਂਦੇ, ਤੇ ਪੰਨਾ ਲੋਡ ਹੋਣ ਤੋਂ ਬਾਅਦ ਆਫ਼ਲਾਈਨ ਵੀ ਚੱਲਦਾ ਹੈ।',
    'faq2.q': 'ਕਿੰਨਾ ਕਾਗ਼ਜ਼ ਤੇ ਸਿਆਹੀ ਅਸਲ ਵਿੱਚ ਬਚੇਗੀ?',
    'faq2.a': 'ਗੂੜ੍ਹੇ ਬੈਕਗ੍ਰਾਊਂਡ ਵਾਲੀਆਂ ਸਲਾਈਡਾਂ ਵਿੱਚ Invert + Ink Saver ਨਾਲ 60–85% ਸਿਆਹੀ ਬਚਦੀ ਹੈ, ਤੇ ਇੱਕ ਸ਼ੀਟ ਤੇ 3–4 ਸਲਾਈਡਾਂ ਲਗਾਉਣ ਨਾਲ ਕਾਗ਼ਜ਼ 60–75% ਘੱਟ ਲੱਗਦਾ ਹੈ। ਸਹੀ ਅੰਕੜੇ ਪ੍ਰੋਸੈਸਿੰਗ ਤੋਂ ਬਾਅਦ ਦਿਖਦੇ ਹਨ।',
    'faq3.q': 'ਕਿਹੜੀਆਂ PDF ਸਭ ਤੋਂ ਵਧੀਆ ਚੱਲਦੀਆਂ ਹਨ?',
    'faq3.a': 'ਗੂੜ੍ਹੇ ਰੰਗ ਵਾਲੇ ਲੈਕਚਰ ਡੈੱਕ (Physics Wallah ਸਟਾਈਲ), ਸਕੈਨ ਕੀਤੇ ਨੋਟਸ ਤੇ ਟੈਕਸਟ-ਪ੍ਰਧਾਨ ਪ੍ਰਜ਼ੈਂਟੇਸ਼ਨ। ਚਿੱਟੇ ਹੈਂਡਆਉਟ ਲਈ Invert ਦੀ ਥਾਂ Grayscale/B&W + 30–50% Ink Saver ਅਜ਼ਮਾਓ।',
    'faq4.q': 'ਹਰ ਡਿਵਾਈਸ ਤੇ ਚੱਲਦਾ ਹੈ?',
    'faq4.a': 'ਹਾਂ — ਫ਼ੋਨ, ਟੈਬਲੈੱਟ, ਲੈਪਟਾਪ ਜਾਂ ਡੈਸਕਟਾਪ। ਪੂਰਾ ਟੂਲ ਕਿਸੇ ਵੀ ਆਧੁਨਿਕ ਬਰਾਊਜ਼ਰ (Chrome, Safari, Edge, Firefox) ਵਿੱਚ ਚੱਲਦਾ ਹੈ, ਕੁਝ ਵੀ ਇੰਸਟਾਲ ਨਹੀਂ ਕਰਨਾ। ਪੁਰਾਣੇ ਫ਼ੋਨ ਤੇ ਵੱਡੀ ਫ਼ਾਈਲ ਨੂੰ ਥੋੜਾ ਸਮਾਂ ਲੱਗਦਾ ਹੈ, ਟੈਬ ਖੁੱਲ੍ਹਾ ਰੱਖੋ।',
    'faq5.q': 'iPhone ਤੇ ਝਲਕ ਖਾਲੀ ਕਿਉਂ ਦਿਖਦੀ ਹੈ?',
    'faq5.a': 'iOS Safari ਪੰਨੇ ਦੇ ਅੰਦਰ PDF ਨਹੀਂ ਦਿਖਾ ਸਕਦਾ। “Open” ਦਬਾ ਕੇ ਪੂਰੇ ਟੈਬ ਵਿੱਚ ਖੋਲ੍ਹੋ ਜਾਂ ਸਿੱਧੇ “Download” ਕਰੋ — ਫ਼ਾਈਲ ਪੂਰੀ ਹੈ ਤੇ ਵਧੀਆ ਛਪੇਗੀ।',
    'faq6.q': 'ਕੀ ਆਉਟਪੁੱਟ PDF ਖੋਜ/ਐਡੀਟ ਹੋ ਸਕਦਾ ਹੈ?',
    'faq6.a': 'ਡਿਫ਼ਾਲਟ ਤੌਰ ਤੇ ਇਹ ਉੱਚ-ਕੁਆਲਟੀ ਇਮੇਜ PDF ਹੈ (ਇਸੇ ਨਾਲ ਸਿਆਹੀ ਬਚਦੀ ਹੈ) — ਪਰ ਸੁਧਾਰ ਵਿੱਚ “ਖੋਜਯੋਗ PDF (OCR)” ਚਾਲੂ ਕਰੋ ਤਾਂ ਅਦਿੱਖ ਟੈਕਸਟ ਲੇਅਰ ਜੁੜ ਜਾਂਦੀ ਹੈ, ਜਿਸ ਨਾਲ ਖੋਜ, ਚੋਣ ਤੇ ਕਾਪੀ ਸਭ ਚੱਲਦਾ ਹੈ। ਪੰਨਾ ਨੰਬਰ ਤੇ ਵੱਖ-ਕਰਨ ਲਾਈਨਾਂ ਹਮੇਸ਼ਾ ਅਸਲੀ ਵੈਕਟਰ ਹੁੰਦੀਆਂ ਹਨ।',
    'faq7.q': 'ਕੀ Android ਐਪ ਹੈ?',
    'faq7.a': 'ਹਾਂ! ਫੁੱਟਰ ਤੋਂ APK ਡਾਊਨਲੋਡ ਕਰੋ — Stable ਬਿਲਡ ਜੰਮਿਆ ਹੋਇਆ ਤੇ ਨਵੇਂ-ਵਰਤਣ ਵਾਲਿਆਂ ਲਈ ਸੁਰੱਖਿਅਤ ਹੈ, ਜਦਕਿ Beta ਬਿਲਡ ਵਿੱਚ ਨਵੇਂ ਫ਼ੀਚਰ ਪਹਿਲਾਂ ਆਉਂਦੇ ਹਨ। ਦੋਵੇਂ ਪੂਰੀ ਤਰ੍ਹਾਂ ਆਫ਼ਲਾਈਨ ਚੱਲਦੇ ਹਨ ਤੇ ਡਾਊਨਲੋਡ ਕੀਤੀ PDF ਸਿੱਧੇ ਫ਼ੋਨ ਵਿੱਚ ਸੇਵ ਹੁੰਦੀ ਹੈ।',
    'faq8.q': 'ਕੀ Google Drive ਜਾਂ Dropbox ਤੋਂ PDF ਲਿਆ ਸਕਦੇ ਹਾਂ?',
    'faq8.a': 'ਹਾਂ — ਅੱਪਲੋਡ ਸਕਰੀਨ ਤੇ “ਕਲਾਉਡ ਤੋਂ ਇੰਪੋਰਟ” ਦਬਾ ਕੇ ਸਾਂਝਾ ਲਿੰਕ ਪੇਸਟ ਕਰੋ (ਫ਼ਾਈਲ “Anyone with the link” ਰੱਖੋ)। ਸਰਵਰ ਉਸ ਨੂੰ ਇੱਕ ਵਾਰ ਲੈ ਕੇ ਸਿੱਧਾ ਤੁਹਾਡੇ ਬਰਾਊਜ਼ਰ ਨੂੰ ਭੇਜਦਾ ਹੈ; ਕੁਝ ਸੇਵ ਨਹੀਂ ਹੁੰਦਾ।',
    'labs.title': 'ਲੈਬਸ',
